# extract to lines
lines = str1.strip().split("\n")
fpr_list = []
for line in lines:
    ft_passed = int(line.split("ft passed ")[1].split(",")[0])
    passed = int(line.split(", passed ")[1].split(",")[0])
    fpr = passed / (ft_passed + passed)
    fpr_list.append(fpr)

avg_fpr = sum(fpr_list) / len(fpr_list)
print("Average False Positive Rate:", avg_fpr)